-- shape_doctor_gather: super-admin-gated SECURITY DEFINER read for the
-- /administration/kind-registry status board (features/content-ir/admin/shape-doctor-server.ts).
--
-- WHY: the board's coverage gates (contract-gap, live-vs-snapshot drift) compare
-- the live registry against service-role-complete baselines (the committed
-- contract manifest + shapes-status snapshot, both generated by CLI scripts
-- reading with SUPABASE_SECRET_KEY). Reading the live side through the viewer's
-- RLS session makes kinds homed in OTHER users' orgs (agent_io contracts follow
-- their agent's org) invisible, fabricating false contract-gap reds and phantom
-- snapshot-only drift (observed 2026-07-15: 20 false reds, 694-vs-714 live count).
-- The board is a super-admin diagnostic surface; its gather must be
-- privilege-complete. Gate is IN the function (protected-resources doctrine) —
-- read-only, no writes, no audit surface needed.

create or replace function public.shape_doctor_gather(p_dataset text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, content_ir, skill
as $$
declare
  v_result jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Forbidden: Super Admin required' using errcode = '42501';
  end if;

  case p_dataset
    when 'kinds' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'kind', kind, 'label', label, 'is_active', is_active,
        'emitted_json_schema', emitted_json_schema, 'sample_data', sample_data,
        'updated_at', updated_at, 'data', data, 'version', version,
        'visibility', visibility, 'metadata', metadata
      )), '[]'::jsonb) into v_result
      from content_ir.kind_definition where deleted_at is null;
    when 'examples' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'kind_definition_id', kind_definition_id,
        'is_canonical', is_canonical, 'data', data, 'updated_at', updated_at
      )), '[]'::jsonb) into v_result
      from content_ir.kind_example where deleted_at is null;
    when 'components' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'kind_definition_id', kind_definition_id, 'platform', platform,
        'role', role, 'component_key', component_key, 'source', source,
        'is_active', is_active, 'is_default', is_default
      )), '[]'::jsonb) into v_result
      from content_ir.kind_component where deleted_at is null;
    when 'surfaces' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'kind_definition_id', kind_definition_id,
        'surface_type', surface_type, 'token', token,
        'parser_strategy', parser_strategy, 'streaming', streaming,
        'is_active', is_active
      )), '[]'::jsonb) into v_result
      from content_ir.kind_surface where deleted_at is null;
    when 'edges' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'parent_definition_id', parent_definition_id,
        'child_definition_id', child_definition_id, 'field_name', field_name
      )), '[]'::jsonb) into v_result
      from content_ir.kind_edge where deleted_at is null;
    when 'render_block_skills' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'skill_id', skill_id, 'label', label, 'body', body
      )), '[]'::jsonb) into v_result
      from skill.definition where skill_type = 'render_block' and deleted_at is null;
    when 'content_blocks' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'label', label, 'template', template
      )), '[]'::jsonb) into v_result
      from public.content_blocks where deleted_at is null;
    else
      raise exception 'shape_doctor_gather: unknown dataset %', p_dataset;
  end case;

  return v_result;
end;
$$;

grant execute on function public.shape_doctor_gather(text) to authenticated;
